import{_ as l,C as a,o as i,c as d,E as r,a4 as s}from"./chunks/framework.2-Vke5-n.js";const n="/arch-guidelines/assets/ipa.drawio.Dth0hjSJ.png",o="/arch-guidelines/assets/juas.drawio.JRigYqkg.png",f="/arch-guidelines/assets/iso_iec25010.drawio.ChX7c4Cn.png",m=JSON.parse('{"title":"Appendix","description":"","frontmatter":{"sidebarDepth":4,"title":"Appendix","author":"フューチャー株式会社","head":[["meta",{"name":"keywords","content":"非機能要件,Appendix"}]]},"headers":[],"relativePath":"documents/forNFR/appendix.md","filePath":"documents/forNFR/appendix.md"}'),g={name:"documents/forNFR/appendix.md"};function y(x,t,p,h,c,b){const e=a("page-title");return i(),d("div",null,[r(e),t[0]||(t[0]=s('<h3 id="非機能に類似する用語" tabindex="-1">非機能に類似する用語 <a class="header-anchor" href="#非機能に類似する用語" aria-label="Permalink to &quot;非機能に類似する用語&quot;">​</a></h3><p>非機能と同じような意味でよく使われる用語に「品質特性」や「アーキテクチャ特性」などがある。</p><ul><li><strong>非機能</strong><br> 機能以外の特性を包括的に指す伝統的な呼び方である。</li><li><strong>品質特性</strong><br> ISO/IEC 25010 のソフトウェア品質モデルに代表される考え方で「明示的ニーズまたは暗黙のニーズを満たすためのソフトウェア製品の能力」と定義されている。</li><li><strong>アーキテクチャ特性</strong><br> 「<a href="https://www.oreilly.co.jp//books/9784873119823/" target="_blank" rel="noreferrer">ソフトウェアアーキテクチャの基礎</a><sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup>」の中で、「ドメインによらない、設計に関する考慮事項をあきらかにするもの」「設計の構造的な側面に影響を与えるもの」「アプリケーションの成功に不可欠な重要なもの」と定められている。</li><li><strong>イリティ</strong><br> 可用性（Availability）、信頼性（Reliability）、保守性（Maintainability）など「-ility」で終わる特性を総称して「イリティ」と呼ぶ。</li></ul><h3 id="非機能フレームワーク" tabindex="-1">非機能フレームワーク <a class="header-anchor" href="#非機能フレームワーク" aria-label="Permalink to &quot;非機能フレームワーク&quot;">​</a></h3><h4 id="ipa-非機能要求グレード" tabindex="-1">IPA 非機能要求グレード <a class="header-anchor" href="#ipa-非機能要求グレード" aria-label="Permalink to &quot;IPA 非機能要求グレード&quot;">​</a></h4><p>IPA（情報処理推進機構）が公開する「非機能要求グレード」は、システム基盤に対する発注者要求の「見える化」を目的に策定されたフレームワークで、ユーザーと開発者の間で非機能要求の認識が食い違うことを防ぐため、検討すべき項目を網羅的にリストアップしそれぞれの要求レベルを段階的に示しているのが特徴である。<br> 非機能要求項目は次の6つの大項目に分類され、その下に35の中項目、118の小項目、238のメトリクス（評価指標）が階層的に整理されている。</p><p><img src="'+n+'" alt="IPA非機能要件グレードの分類"></p><div class="tip custom-block"><p class="custom-block-title">現場での活用における注意点</p><p>本グレードは長らく国内のデファクトスタンダードとして活用されているが、IPAにおける該当事業（更新・保守）は既に終了している。</p><ul><li><a href="https://www.ipa.go.jp/archive/digital/iot-en-ci/jyouryuu/hikinou/ent03-b-1.html" target="_blank" rel="noreferrer">非機能要求グレード本体（日本語版）使用条件 | アーカイブ | IPA 独立行政法人 情報処理推進機構</a></li></ul><p>そのため、記載されている技術前提やメトリクスが、最新のクラウドアーキテクチャや開発手法の実態と合致しない部分も存在する。あくまで検討の漏れを防ぐためのベースラインと割り切り、AI要件など最新の技術トレンドに合わせてプロジェクト独自の要件へカスタマイズすることが不可欠であり、それが腕の見せ所である。</p></div><h4 id="juas-非機能要求仕様定義ガイドライン" tabindex="-1">JUAS 非機能要求仕様定義ガイドライン <a class="header-anchor" href="#juas-非機能要求仕様定義ガイドライン" aria-label="Permalink to &quot;JUAS 非機能要求仕様定義ガイドライン&quot;">​</a></h4><p>JUAS（日本情報システム・ユーザー協会）が2008年に発行した「非機能要求仕様定義ガイドライン」は、IPA 非機能要求グレードと並んで国内でよく参照される。「ユーザー（発注者）視点」「検証可能性の重視」を特徴とし、非機能要件230項目について「確認すべき項目 / 確認すべきプロセス / 検証方法 / 必要なドキュメント」を整理している点が、要求レベルの提示に重きを置く IPA とは立脚点が異なる。大分類は次の10項目で、後述する ISO/IEC 9126（ISO/IEC 25010 の前身）の品質特性を下敷きに、ユーザー視点で再構成したものとなっている。<br> ただし、2008年発行という時期もあり、クラウドサービスの普及やセキュリティインシデントの多様化など、近年のシステム開発のアプローチを必ずしも反映していない点には留意が必要である。</p><p><img src="'+o+'" alt="JUASの非機能要求の分類"></p><h4 id="iso-iec-25010-製品品質モデル" tabindex="-1">ISO/IEC 25010 製品品質モデル <a class="header-anchor" href="#iso-iec-25010-製品品質モデル" aria-label="Permalink to &quot;ISO/IEC 25010 製品品質モデル&quot;">​</a></h4><p>ISO/IEC 25010 はソフトウェアおよびシステムの品質モデルを定義する国際規格で、SQuaRE（Systems and software Quality Requirements and Evaluation）シリーズの中核をなす。ISO/IEC 9126 と ISO/IEC 14598 を統合した規格として2011年に発行され、2023年11月に大きな改訂が行われた（ISO/IEC 25010:2023）。 最新版の製品品質モデルは次の9つの品質特性で構成される。各品質特性はさらに副品質特性に細分化される。<br> 2011年版から大きく変わった点として、「使用性（Usability）」が「相互作用性（Interaction Capability）」に、「移植性（Portability）」が「柔軟性（Flexibility）」（移植性はその副特性に位置づけ）に再編され、新たに「安全性（Safety）」が独立した品質特性として追加された。</p><p><img src="'+f+'" alt="ISO/IEC 25010のシステム・ソフトウェア製品品質の分類"></p><p>※図は2023年大改定前のものである。</p><h4 id="デジタル社会推進標準ガイドライン-群" tabindex="-1">デジタル社会推進標準ガイドライン（群） <a class="header-anchor" href="#デジタル社会推進標準ガイドライン-群" aria-label="Permalink to &quot;デジタル社会推進標準ガイドライン（群）&quot;">​</a></h4><p>デジタル庁が策定する政府情報システムの整備・管理に関する政府共通ルールで、デジタル庁発足以前から内閣官房によって「デジタル・ガバメント推進標準ガイドライン」として運用されてきたものを継承・改称している。要件定義書に記載すべき非機能要件として、次の項目を定めている。</p><ul><li>ユーザビリティ及びアクセシビリティ</li><li>システム方式</li><li>規模</li><li>性能</li><li>信頼性</li><li>拡張性</li><li>上位互換性</li><li>中立性</li><li>継続性</li><li>情報セキュリティ</li><li>情報システム稼働環境</li><li>データマネジメントに関する事項</li><li>テスト</li><li>移行</li><li>引継ぎ</li><li>教育</li><li>運用</li><li>保守</li></ul><h2 id="可用性の定義項目チェックリスト" tabindex="-1">可用性の定義項目チェックリスト <a class="header-anchor" href="#可用性の定義項目チェックリスト" aria-label="Permalink to &quot;可用性の定義項目チェックリスト&quot;">​</a></h2><p>可用性の厳密な定義項目と、設定例をまとめる。本編「可用性」の項目マップを、実務で使えるレベルまで具体化したものである。IPA 非機能要求グレードのような網羅的な確認をしたいときの叩き台として使うとよい。</p><p>ただし、すべてのシステムで全項目を埋める必要はない。多くのシステムは基本項目（運用スケジュール・目標稼働率・RTO/RPO）だけで足り、ミッションクリティカルなシステムほど下位の項目まで詰めていく。</p><p><strong>1. 継続性 ― いつ・どれだけ使えるか</strong></p><table tabindex="0"><thead><tr><th style="text-align:left;">分類</th><th style="text-align:left;">定義項目</th><th style="text-align:left;">値の例</th></tr></thead><tbody><tr><td style="text-align:left;">運用スケジュール</td><td style="text-align:left;">運用時間（通常）</td><td style="text-align:left;">24時間365日無停止 / 業務時間内（9–17時） / 夜間のみ停止</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">運用時間（特定日）</td><td style="text-align:left;">祝日・年末年始も通常どおり / 特定日のみ停止可</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">計画停止の有無・許容時間</td><td style="text-align:left;">あり（月間最大 XX 時間） / なし（ゼロダウンタイム必須）</td></tr><tr><td style="text-align:left;">稼働率</td><td style="text-align:left;">目標稼働率</td><td style="text-align:left;">99％ / 99.9％ / 99.99％ / 99.999%</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">計算条件の明記</td><td style="text-align:left;">計画停止を除く / 大規模災害を除く / 外部要因を除く / 月間・年間集計</td></tr><tr><td style="text-align:left;">目標復旧水準</td><td style="text-align:left;">RTO（目標復旧時間）</td><td style="text-align:left;">2時間以内 / 4時間以内 / 1営業日以内 / 数日以内</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">RPO（許容データ損失）</td><td style="text-align:left;">ほぼゼロ / 日次（1営業日前） / 週次（5営業日前）</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">RLO（目標復旧レベル）</td><td style="text-align:left;">全機能復旧 / 主要業務のみ / 縮退（参照のみ）</td></tr></tbody></table><p><strong>2. 耐障害性 ― そもそも止まりにくくする</strong></p><table tabindex="0"><thead><tr><th style="text-align:left;">定義項目</th><th style="text-align:left;">値の例</th></tr></thead><tbody><tr><td style="text-align:left;">対象業務範囲</td><td style="text-align:left;">全業務 / 外部向けオンライン系のみ / 内部バッチ系のみ</td></tr><tr><td style="text-align:left;">サーバー冗長化</td><td style="text-align:left;">非冗長 / 負荷分散 / クラスタ / Active-Active / Multi-AZ</td></tr><tr><td style="text-align:left;">コンポーネント冗長化（電源・ディスク・NW）</td><td style="text-align:left;">RAID 相当 / 分散ストレージ / 複数 ISP</td></tr><tr><td style="text-align:left;">SPOF 排除対象</td><td style="text-align:left;">重要コンポーネント全て / サーバー・ストレージ・NW まで / 外部依存含む</td></tr><tr><td style="text-align:left;">同時障害耐性（＝業務継続の要求度）</td><td style="text-align:left;">単一障害時も継続 / 二重障害時も切替時間内で継続 / リージョン障害は DR に委ねる</td></tr><tr><td style="text-align:left;">サービス切り替え時間（フェイルオーバー）</td><td style="text-align:left;">60秒未満 / 5分以内 / 15分以内 / 60分以内</td></tr><tr><td style="text-align:left;">フェイルオーバーの自動 / 手動</td><td style="text-align:left;">自動 / 手動（承認あり）</td></tr><tr><td style="text-align:left;">縮退運用レベル（＝RLO と対応）</td><td style="text-align:left;">フル機能 / 主要業務のみ / 参照のみ</td></tr></tbody></table><p><strong>3. 災害対策・BCP ― 大規模・広域障害への備え</strong></p><table tabindex="0"><thead><tr><th style="text-align:left;">定義項目</th><th style="text-align:left;">値の例</th></tr></thead><tbody><tr><td style="text-align:left;">DR サイトの種類</td><td style="text-align:left;">ホット / ウォーム / コールドスタンバイ / クラウド Multi-Region</td></tr><tr><td style="text-align:left;">DR 発動基準・切替時間</td><td style="text-align:left;">RTO に準拠 / 事前定義トリガー（地震規模・DC 全損など）</td></tr><tr><td style="text-align:left;">大規模災害時のシステム再開目標</td><td style="text-align:left;">1日以内 / 3日以内 / 1週間以内 / 1ヶ月以内 / 再開不要</td></tr><tr><td style="text-align:left;">復旧優先順位</td><td style="text-align:left;">Critical → High → Medium の順序と復旧順</td></tr></tbody></table><p><strong>4. 可用性を支える運用・観測</strong><br> これらは可用性そのものの定義というより運用保守性の項目だが、可用性の維持に直結するため参照として掲げる。</p><table tabindex="0"><thead><tr><th style="text-align:left;">定義項目</th><th style="text-align:left;">値の例</th></tr></thead><tbody><tr><td style="text-align:left;">無停止保守の要否</td><td style="text-align:left;">月間最大 XX 時間の停止可 / ゼロ停止（Blue-Green 等）</td></tr><tr><td style="text-align:left;">監視・検知時間</td><td style="text-align:left;">障害検知からアラートまで5分以内 / 自動検知必須</td></tr><tr><td style="text-align:left;">障害対応体制</td><td style="text-align:left;">オンコール体制 / エスカレーション初動30分以内</td></tr><tr><td style="text-align:left;">可用性確認・テスト範囲</td><td style="text-align:left;">業務停止となる障害の全範囲 / 重要業務のみ</td></tr><tr><td style="text-align:left;">耐障害性テストの頻度</td><td style="text-align:left;">四半期1回 / 年2回 / Chaos Engineering 定期実施</td></tr></tbody></table><hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p>ソフトウェアアーキテクチャの基礎 Mark Richards （著）, Neal Ford （著）, 島田 浩二 （翻訳） <a href="#fnref1" class="footnote-backref">↩︎</a></p></li></ol></section>',31))])}const I=l(g,[["render",y]]);export{m as __pageData,I as default};
